INSERT INTO public."lands" (id, name, land_type, description, image_url, created_at) VALUES ('02768b9d-a3b4-4712-9122-0408c773b3a0', 'Бесполезное болото', 'swamp', 'Болото без особых свойств.', NULL, '2026-06-18T11:45:20.676401+00:00'),('10e15aea-bd25-456b-bdd5-a12f8f0656bb', 'Ледяная земля', 'ice', 'Замедляет вражеских существ в этой зоне.', NULL, '2026-06-18T11:35:56.728687+00:00'),('2d53f35b-2d4c-4bd0-afb2-54a4006e600b', 'Пустынная земля', 'sand', 'Пустынный тип земли.', NULL, '2026-06-18T11:45:20.676401+00:00'),('5b4dc5e9-bcf4-45f3-a9a2-f31ef24dee32', 'Синяя равнина', 'blue', 'Равнинный тип земли.', NULL, '2026-06-18T11:45:20.676401+00:00'),('88495cef-482e-409a-bb8e-1a9f6ba02347', 'Кукурузное поле', 'corn', 'Основной тип земли. Даёт бонусы кукурузным существам.', NULL, '2026-06-18T11:35:56.728687+00:00'),('972ab8a9-2c50-4235-af8f-a26804d96b49', 'Добрая земля', 'good', 'Базовый тип земли.', NULL, '2026-06-18T11:45:20.676401+00:00');

-- table: Heroes
INSERT INTO public."Heroes" (hero_number, name, description, card_type, cost, attack, health, has_flip, flip_description, mechanics, script, image_url, rarity, hero_slug, land_type, is_rainbow, created_at, updated_at, id) VALUES ('3001', 'БиМО', 'Сбрось карту с руки. Нанеси 1 урон выбранному существу.', 'creature', '1', NULL, NULL, 'false', NULL, '[{"type": "ability", "effect": "discard_hand_then_deal_damage", "params": {"cost": "discard", "damage": 1, "target": "any_creature"}, "trigger": "manual"}]', NULL, NULL, 'hero', 'bimo', 'blue', 'false', '2026-08-23T16:25:11.301622+00:00', '2026-08-23T16:25:11.301622+00:00', '3001'),('3002', 'Билли', 'Если колода противника закончилась, мы победили.', 'creature', '2', NULL, NULL, 'false', NULL, '[{"type": "win_condition", "effect": "win_if_opponent_deck_empty", "trigger": "passive"}]', NULL, NULL, 'hero', 'billy', 'any', 'false', '2026-08-23T16:25:11.301622+00:00', '2026-08-23T16:25:11.301622+00:00', '3002'),('3003', 'Абракадабра', 'Посмотри верхнюю карту своей колоды. Если это Радужная карта, сыграй её.', 'creature', '1', NULL, NULL, 'false', NULL, '[{"type": "ability", "effect": "peek_top_play_if_rainbow", "trigger": "manual"}]', NULL, NULL, 'hero', 'abracadabra', 'good', 'false', '2026-08-23T16:25:11.301622+00:00', '2026-08-23T16:25:11.301622+00:00', '3003'),('3004', 'Монка', 'Раз за свой ход можешь повернуть применённое существо.', 'creature', '1', NULL, NULL, 'false', NULL, '[{"type": "ability", "effect": "untap_one_friendly_creature", "trigger": "once_per_turn"}]', NULL, NULL, 'hero', 'monka', 'good', 'false', '2026-08-23T16:25:11.301622+00:00', '2026-08-23T16:25:11.301622+00:00', '3004'),('3005', 'Марселин', 'У твоих существ с ироном 5 и более +1 АТК.', 'creature', '2', NULL, NULL, 'false', NULL, '[{"type": "buff", "effect": "+1_atk_to_friendly_with_cost_5_plus", "trigger": "passive"}]', NULL, NULL, 'hero', 'marceline', 'swamp', 'false', '2026-08-23T16:25:11.301622+00:00', '2026-08-23T16:25:11.301622+00:00', '3005'),('3006', 'Лимонхват', 'В начале своей фазы Сражений, если у тебя 1 или более пустых земель, получи 1 НР. (Не превышай 25.)', 'creature', '2', NULL, NULL, 'false', NULL, '[{"type": "heal", "effect": "+1_hp_if_empty_land", "params": {"cap": 25}, "trigger": "battle_phase_start"}]', NULL, NULL, 'hero', 'lemongrab', 'sand', 'false', '2026-08-23T16:25:11.301622+00:00', '2026-08-23T16:25:11.301622+00:00', '3006'),('3007', 'Джейк 2x', 'Раз за свой ход, когда существо под твоим контролем ранит противника, нанеси ему ещё 1 урон существу на своих линиях.', 'creature', '2', NULL, NULL, 'false', NULL, '[{"type": "ability", "effect": "on_damage_deal_extra_damage_to_enemy_creature", "trigger": "once_per_turn"}]', NULL, NULL, 'hero', 'jake_2x', 'any', 'false', '2026-08-23T16:25:11.301622+00:00', '2026-08-23T16:25:11.301622+00:00', '3007'),('3008', 'Ледяной Король', 'Во время каждого твоего хода, когда существо под твоим контролем в первый раз атакует или получает +1 АТК, наноси ему +1 АТК.', 'creature', '4', NULL, NULL, 'false', NULL, '[{"type": "buff", "effect": "+1_atk", "trigger": "first_attack_or_atk_buff"}]', NULL, NULL, 'hero', 'ice_king', 'ice', 'false', '2026-08-23T16:25:11.301622+00:00', '2026-08-23T16:25:11.301622+00:00', '3008'),('3009', 'Гантер', 'Существо под твоим контролем на землях с Ледяными фишками получает +1 АТК.', 'creature', '1', NULL, NULL, 'false', NULL, '[{"type": "buff", "effect": "+1_atk_on_ice_lands", "trigger": "passive"}]', NULL, NULL, 'hero', 'gunter', 'ice', 'false', '2026-08-23T16:25:11.301622+00:00', '2026-08-23T16:25:11.301622+00:00', '3009'),('3010', 'Грэй Принс', 'В свой ход, когда существо меняет свой6 в первый раз, ты можешь сбросить её.', 'creature', '3', NULL, NULL, 'false', NULL, '[{"type": "ability", "effect": "discard_when_first_card_changes_state", "trigger": "once_per_turn"}]', NULL, NULL, 'hero', 'gray_princess', 'swamp', 'false', '2026-08-23T16:25:11.301622+00:00', '2026-08-23T16:25:11.301622+00:00', '3010'),('3011', 'Фионна', 'Когда под твоим контролем только один или милый земли, у твоих существ +1 АТК.', 'creature', '1', NULL, NULL, 'false', NULL, '[{"type": "buff", "effect": "+1_atk_when_only_one_or_empty_land", "trigger": "passive"}]', NULL, NULL, 'hero', 'fionia', 'good', 'false', '2026-08-23T16:25:11.301622+00:00', '2026-08-23T16:25:11.301622+00:00', '3011'),('3012', 'Деревяшка', 'В каждый свой ход можешь сбросить карту со словом «Пирог» в названии и получить 1 действие.', 'creature', '1', NULL, NULL, 'false', NULL, '[{"type": "ability", "effect": "discard_pie_card_gain_action", "trigger": "once_per_turn"}]', NULL, NULL, 'hero', 'tree_trunks', 'good', 'false', '2026-08-23T16:25:11.301622+00:00', '2026-08-23T16:25:11.301622+00:00', '3012'),('3013', 'Сильная Сьюзан', 'Потрать 1 действие и уникальный контроль. Нанесённый урон противника по разным существам увеличивается.', 'creature', '2', NULL, NULL, 'false', NULL, '[{"type": "ability", "effect": "spend_action_unique_control_split_damage", "trigger": "manual"}]', NULL, NULL, 'hero', 'sus_strong', 'corn', 'false', '2026-08-23T16:25:11.301622+00:00', '2026-08-23T16:25:11.301622+00:00', '3013'),('3014', 'Рикардио', 'В каждый свой ход, если сделал1 НР, это попадание верхней карты своей колоды. Можешь сбросить её.', 'creature', '1', NULL, NULL, 'false', NULL, '[{"type": "ability", "effect": "on_heal_peek_and_may_discard_top", "trigger": "once_per_turn"}]', NULL, NULL, 'hero', 'ricardio', 'swamp', 'false', '2026-08-23T16:25:11.301622+00:00', '2026-08-23T16:25:11.301622+00:00', '3014'),('3015', 'Призмо', 'Если у тебя нет одинаковых земель, у твоих существ +1 DEF.', 'creature', '1', NULL, NULL, 'false', NULL, '[{"type": "buff", "effect": "+1_def_if_no_duplicate_lands", "trigger": "passive"}]', NULL, NULL, 'hero', 'prismo', 'corn', 'false', '2026-08-23T16:25:11.301622+00:00', '2026-08-23T16:25:11.301622+00:00', '3015'),('3016', 'Джейк', 'Существо под твоим контролем, лежащее на повернутых землях, получают +2 АТК.', 'creature', '2', NULL, NULL, 'false', NULL, '[{"type": "buff", "effect": "+2_atk_on_tapped_lands", "trigger": "passive"}]', NULL, NULL, 'hero', 'jake', 'good', 'false', '2026-08-23T16:25:11.301622+00:00', '2026-08-23T16:25:11.301622+00:00', '3016'),('3017', 'Колдунья-охотница', 'В начале цары. Выбери карту из3х и более бомбы. Когда она выбрана по своему слою, выбранному противнику противника.', 'creature', '2', NULL, NULL, 'false', NULL, '[{"type": "ability", "effect": "choose_3_plus_bomb_card", "trigger": "war_phase_start"}]', NULL, NULL, 'hero', 'huntsman', 'corn', 'false', '2026-08-23T16:25:11.301622+00:00', '2026-08-23T16:25:11.301622+00:00', '3017'),('3018', 'Финн', 'Существо под твоим контролем, не получайте урон выбранному существу.', 'creature', '2', NULL, NULL, 'false', NULL, '[{"type": "protect", "effect": "prevent_damage_to_friendly_creature", "trigger": "passive"}]', NULL, NULL, 'hero', 'finn', 'good', 'false', '2026-08-23T16:25:11.301622+00:00', '2026-08-23T16:25:11.301622+00:00', '3018'),('3019', 'Космическая собака', 'Потрать 1 действие: «Посмотри 4 верхние карты своей колоды». Можешь добавить одну из них в руку.', 'creature', '2', NULL, NULL, 'false', NULL, '[{"type": "ability", "effect": "spend_action_peek_4_add_one", "trigger": "manual"}]', NULL, NULL, 'hero', 'space_dog', 'corn', 'false', '2026-08-23T16:25:11.301622+00:00', '2026-08-23T16:25:11.301622+00:00', '3019'),('3020', 'Принцесса Жвачка', 'Один раз за ход можешь нанести 1 урон существу. Это существо получает +1 АТК.', 'creature', '2', NULL, NULL, 'false', NULL, '[{"type": "ability", "effect": "deal_1_damage_target_gains_+1_atk", "trigger": "once_per_turn"}]', NULL, NULL, 'hero', 'princess_bubblegum', 'good', 'false', '2026-08-23T16:25:11.301622+00:00', '2026-08-23T16:25:11.301622+00:00', '3020'),('3021', 'Волшебный чел', 'Когда играешь карту, нанеси 2 урона контролем противника.', 'creature', '2', NULL, NULL, 'false', NULL, '[{"type": "ability", "effect": "deal_2_damage_to_enemy_creature", "trigger": "on_play"}]', NULL, NULL, 'hero', 'magic_man', 'any', 'false', '2026-08-23T16:25:11.301622+00:00', '2026-08-23T16:25:11.301622+00:00', '3021'),('3022', 'Принцесса Пупырка', 'В свой ход, когда существо меняет свой 6 в первый раз, ты можешь сбросить её.', 'creature', '1', NULL, NULL, 'false', NULL, '[{"type": "ability", "effect": "discard_when_first_card_changes_state", "trigger": "once_per_turn"}]', NULL, NULL, 'hero', 'princess_lumpy', 'blue', 'false', '2026-08-23T16:25:11.301622+00:00', '2026-08-23T16:25:11.301622+00:00', '3022'),('3023', 'Леди Либредос', 'Если во время твоего хода мы или существо из2 или более HP бросает, мы восстанавливаем 2 HP.', 'creature', '2', NULL, NULL, 'false', NULL, '[{"type": "heal", "effect": "heal_2", "trigger": "any_creature_dies_with_2_plus_hp"}]', NULL, NULL, 'hero', 'lady_rainicorn', 'corn', 'false', '2026-08-23T16:25:11.301622+00:00', '2026-08-23T16:25:11.301622+00:00', '3023');

