alse', NULL, NULL, NULL, NULL),('02dd3f6e-956a-e2b8-a8d0-8520a39563a2', '114', 'Колдунья кукурузы', 'Колдунья кукурузы получает +1 ATK за каждое другое Кукурузное существо под твоим контролем.', 'creature', '1', '0', '0', 'false', NULL, '[]', 'https://<supabase-project>.supabase.co/storage/v1/object/public/card-images/cards/02dd3f6e-956a-e2b8-a8d0-8520a39563a2.png', '2026-08-11T13:56:56.668878+00:00', '2026-08-11T14:19:04.196007+00:00', 'corn', 'false', NULL, 'CP1', 'Jake', NULL),('02ebf806-906c-49a6-8fef-7881087ce1c3', '283', 'Последний раунд!', 'Выбранное существо под твоим контролем получает +2 ATK за каждое неактивное существо под твоим контролем (на момент вступления в игру).', 'spell', '1', '0', '0', 'false', NULL, '[]', 'https://<supabase-project>.supabase.co/storage/v1/object/public/card-images/cards/02ebf806-906c-49a6-8fef-7881087ce1c3.png', '2026-08-11T13:57:04.512802+00:00', '2026-08-11T14:19:07.142986+00:00', 'any', 'true', NULL, NULL, NULL, NULL),('03082b08-4731-612d-52c3-0837ac27fe52', '21', 'Великолепный замок', 'Твое существо получает +3 DEF на этой линии.', 'building', '0', '0', '0', 'false', NULL, '[]', 'https://<supabase-project>.supabase.co/storage/v1/object/public/card-images/cards/03082b08-4731-612d-52c3-0837ac27fe52.png', '2026-08-11T13:56:54.669194+00:00', '2026-08-16T18:45:19.148455+00:00', 'any', 'true', NULL, 'CP1', 'Jake', NULL),('03765705-5e6c-4fb8-bfd0-9f022aaad97b', '203', 'Мороженная рыба', 'Когда Мороженная рыба наносит урон существу, можешь заморозить землю на этой линии.', 'creature', '1', '1', '8', 'false', NULL, '[]', 'https://<supabase-project>.supabase.co/storage/v1/object/public/card-images/cards/03765705-5e6c-4fb8-bfd0-9f022aaad97b.png', '2026-08-11T13:57:01.514989+00:00', '2026-08-11T14:19:06.167967+00:00', 'ice', 'false', NULL, NULL, NULL, NULL),('0612c379-8d7c-4ec0-ac73-0e3fca13cf85', '349', 'Ты жжошь!', 'Переверни выбранную землю лицом вниз до начала твоего следующего хода.', 'spell', '0', '0', '0', 'false', NULL, '[]', '